=== package.json ===
{
  "name": "claudinite-website",
  "version": "1.0814.22",
  "private": true,
  "description": "The claudinite.com marketing site — static, hand-authored. This file exists to carry the released version; there is no build and no dependency.",
  "type": "module",
  "scripts": {
    "bump-version": "node scripts/bump-version.mjs"
  }
}

1	// Land a task's delivered pull request under the REPO's delivery settings — the
2	// single home for the auto-merge nuances every PR-delivering task shares. These
3	// helpers were built inside the baselining worker (#455/#565/#649/#677/#690);
4	// they live here because the other `merged-pr` tasks hit the identical failure
5	// shapes (an arm rejected "clean status" on an ungated base stranding a green PR
6	// forever), and two copies of this precedence is exactly the drift the corpus
7	// forbids.
8	//
9	// The contract that keeps tasks simple: a task declares only its outcome CEILING
10	// (`expected_outcome: 'merged-pr'` — it MAY land a PR). Whether the PR actually
11	// lands unreviewed is the MEMBER REPO's call — `maintenance.delivery` in
12	// `.claudinite-checks.json`, where `review` degrades every merged-pr task to
13	// open-pr (member config wins, per-project-scheduling DESIGN §1). Tasks stay
14	// unaware of that setting by construction: they hand their PR to landDelivery()
15	// (directly, or through deliver-generated.mjs) and the repo-shape nuances stay
16	// here:
17	//
18	//   - `review` member          → the PR is opened and LEFT — never armed, never merged.
19	//   - no pull_request CI at all → MERGE directly. GitHub's auto-merge is a queue
20	//     for checks; with nothing to queue behind, the arm is rejected ("Pull
21	//     request is in clean status") every time, and while that rejection was
22	//     swallowed a repo that asked for auto-merge got no merge at all.
23	//   - CI present, but the base branch REQUIRES nothing → the arm is equally
24	//     doomed (same clean-status rejection, #677): skip it, wait for this run's
25	//     own dispatched evidence, and land on it (verify-then-merge).
26	//   - a base gate present — or unreadable, which is never read as absent → ARM,
27	//     with the landing poll as fallback when the arm is rejected (auto-merge
28	//     disabled repo-side, or a pull_request run parked at `action_required`).
29	//
30	// A branch pushed and a PR opened over the Action's GITHUB_TOKEN emit no
31	// pull_request run of their own (GitHub's recursion guard, #565), so
32	// landDelivery also STARTS the PR's checks via workflow_dispatch before deciding
33	// anything — the checks an arm would wait on must exist to conclude.
34	//
35	// The AGENT lane (executor subagents, MCP writes) cannot run this module; its
36	// prose twin is `deliver-pr.md` beside this file, and the two must keep saying
37	// the same thing — a nuance changed here changes there in the same commit.
38	//
39	// DISPOSAL lives here too (`openDeliveredPull` / `disposeOpenPull`). It began as
40	// baselining's private close-and-recut, kept in that worker while it was the only
41	// task that re-cut a per-cycle branch. The update flows re-cut one exactly the same
42	// way, and #787 is what the second copy would have cost: the update runner promised
43	// "leaving it open for the next run to dispose of" with no code anywhere that could
44	// keep the promise, so a PR its cycle could not land was superseded by a duplicate
45	// the next cycle opened instead. One precedence, one home.
46	
47	const API = 'https://api.github.com';
48	
49	async function gh(token, path, { method = 'GET', body } = {}) {
50	  const res = await fetch(`${API}${path}`, {
51	    method,
52	    headers: {
53	      authorization: `Bearer ${token}`,
54	      accept: 'application/vnd.github+json',
55	      'x-github-api-version': '2022-11-28',
56	      ...(body ? { 'content-type': 'application/json' } : {}),
57	    },
58	    body: body ? JSON.stringify(body) : undefined,
59	  });
60	  let json = null;
61	  try { json = await res.json(); } catch { /* empty body */ }
62	  return { status: res.status, json };
63	}
64	
65	// --- the member's delivery preference ----------------------------------------
66	
67	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
68	// `pr` → review are the permanent legacy aliases (the maintenance-lane tolerance);
69	// anything else is invalid (null) and fails the run rather than guessing.
70	export function normalizeDelivery(raw) {
71	  const v = String(raw ?? '').trim();
72	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
73	  if (v === 'review' || v === 'pr') return 'review';
74	  return null;
75	}
76	
77	// The default a repo gets when it never declared one.
78	export const DEFAULT_DELIVERY = 'auto-merge';
79	
80	// `maintenance.delivery` is always EXPLICIT — but a key that is simply absent is
81	// DRIFT, not an error. A repo adopted before the key existed, or one whose key
82	// was hand-removed, would otherwise fail its scheduled tasks every night forever
83	// with nothing that could ever fix it (the only writer is check_the_world --init,
84	// which runs once at adoption; baselining's converge is what repairs the drift).
85	// So: resolve to the default and carry on — `materialize: true` tells the one
86	// caller that CAN write the repair (the update converge) to do so; everyone else just uses
87	// the resolved value.
88	//
89	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
90	// this code cannot honour, and silently substituting a default would deliver
91	// the opposite of what they asked for. That still fails the run (delivery: null).
92	//
93	// Returns { delivery, materialize } — `delivery` null only for the unrecognized
94	// case. A content-free value (empty/whitespace) carries no intent, so it is
95	// treated as absent rather than as a typo.
96	export function resolveDelivery(raw) {
97	  if (raw == null || String(raw).trim() === '') {
98	    return { delivery: DEFAULT_DELIVERY, materialize: true };
99	  }
100	  return { delivery: normalizeDelivery(raw), materialize: false };
101	}
102	
103	// The same resolution, from the raw TEXT of a repo's .claudinite-checks.json —
104	// the shape a caller reading the file off a git blob has in hand. Unparsable or
105	// absent text resolves like a missing key: default, not failure (the file's
106	// integrity is check_the_world's problem, not the delivery step's).
107	export function deliveryFromChecks(text) {
108	  let parsed = null;
109	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
110	  return resolveDelivery(parsed?.maintenance?.delivery);
111	}
112	
113	// --- CI dispatch on the delivered PR (#565) -----------------------------------
114	// The GITHUB_TOKEN push/PR-open emits no pull_request run (GitHub's recursion
115	// guard), so the delivery starts the PR's checks itself: dispatch every workflow
116	// that WOULD have run on pull_request and CAN be dispatched.
117	//
118	// "Suppresses" is only half true, and the other half is #455/#205/#95: on some
119	// members GitHub CREATES the pull_request run and parks it at `action_required`
120	// awaiting an approval nobody clicks. The dispatch above still supplies the real
121	// green, but the parked run is what auto-merge refuses over — which is why
122	// arming is not the end of the story and pullDisposition exists.
123	//
124	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
125	// `on:` block (no YAML parser in the corpus). It covers the shapes workflows
126	// actually use: a block map of trigger keys (with or without nested config), the
127	// inline scalar, and the inline list.
128	export function workflowTriggers(yaml) {
129	  const lines = String(yaml ?? '').split('\n');
130	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
131	  if (onAt === -1) return [];
132	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
133	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
134	  const triggers = [];
135	  let childIndent = null;
136	  for (let i = onAt + 1; i < lines.length; i += 1) {
137	    const line = lines[i];
138	    if (!line.trim() || line.trim().startsWith('#')) continue;
139	    const indent = line.length - line.trimStart().length;
140	    if (indent === 0) break;                        // next top-level key — on: is done
141	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
142	    if (indent !== childIndent) continue;           // nested config under a trigger
143	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
144	    if (m) triggers.push(m[1]);
145	  }
146	  return triggers;
147	}
148	
149	// The dispatch plan over the repo's workflow files ({name, content} each):
150	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
151	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
152	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
153	// fix, and silence here would read as "no CI expected" when CI was expected).
154	// A workflow with no pull_request trigger is never touched — dispatchable-but-
155	// unrelated workflows (a release orchestrator, say) must not fire on a delivery.
156	export function ciDispatchPlan(files) {
157	  const dispatch = [];
158	  const missing = [];
159	  for (const { name, content } of files ?? []) {
160	    const triggers = workflowTriggers(content);
161	    if (!triggers.includes('pull_request')) continue;
162	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
163	  }
164	  return { dispatch, missing };
165	}
166	
167	// The I/O half of the CI dispatch: read the workflow files as they exist ON THE
168	// DELIVERED BRANCH (the delivery may itself have changed them), plan with
169	// ciDispatchPlan, POST a dispatch per selected workflow, and log every outcome —
170	// a silent no-checks PR is exactly the failure mode this exists to close. Needs
171	// the scheduler workflow's `actions: write` (a read-only token 403s the POST
172	// silently — the store-release lesson).
173	// Returns { dispatch, missing, started }: `dispatch`/`missing` are the PLAN
174	// (what the tree says should run), `started` the dispatches GitHub actually
175	// accepted (204). The landing poll must wait only on `started` — a POST that
176	// 403'd (the scheduler workflow missing `actions: write`, the canon's own copy
177	// on 2026-08-08) starts nothing, and counting the plan had the poll waiting for
178	// a run that could never come.
179	export async function dispatchCiRuns({ token, repo, branch, log = console.log }) {
180	  const ref = encodeURIComponent(branch);
181	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
182	  const files = [];
183	  for (const entry of Array.isArray(dir) ? dir : []) {
184	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
185	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
186	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
187	  }
188	  const { dispatch, missing } = ciDispatchPlan(files);
189	  for (const name of missing) {
190	    log(`${name} runs on pull_request but has no workflow_dispatch trigger — `
191	      + 'cannot start it on the delivered PR; add `workflow_dispatch:` under its `on:` to let the delivery run it');
192	  }
193	  if (!dispatch.length && !missing.length) {
194	    log('no pull_request-triggered workflow — the delivered PR has no checks to wait for');
195	  }
196	  const started = [];
197	  for (const name of dispatch) {
198	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
199	      method: 'POST', body: { ref: branch },
200	    });
201	    if (res.status === 204) { started.push(name); log(`dispatched ${name} on ${branch} — the delivered PR gets its checks`); }
202	    else {
203	      log(`could not dispatch ${name} on ${branch} (${res.status})`
204	        + (res.status === 403 ? ' — the scheduler workflow needs `actions: write` (a read token 403s this POST silently)' : ''));
205	    }
206	  }
207	  return { dispatch, missing, started };
208	}
209	
210	// --- opening the PR ------------------------------------------------------------
211	
212	// Why the PR-open POST must be status-checked, as a pure predicate: null when
213	// the PR was created, else the message to fail on.
214	//
215	// This is the one call whose silent failure is invisible AND self-perpetuating:
216	// a cycle that pushes its branch but fails to open the PR leaves nothing for the
217	// next cycle to find, branches pile up nightly, and the run still reports `ok`
218	// because nothing read the status. The usual cause is repo-level and invisible
219	// from here — "Allow GitHub Actions to create and approve pull requests" is off
220	// and the POST 403s — so the message names that remedy rather than leaving a
221	// bare status code.
222	export function pullCreateError(status, json) {
223	  if (status === 201 && json?.number) return null;
224	  const detail = json?.message ?? `HTTP ${status}`;
225	  return `${detail} — if this is the Actions PR permission, enable Settings → Actions`
226	    + ' → General → "Allow GitHub Actions to create and approve pull requests"';
227	}
228	
229	// --- the delivery decision -------------------------------------------------------
230	
231	// How an `auto-merge` member's PR actually lands, given whether this repo has any
232	// pull_request-triggered workflow at all.
233	//
234	// GitHub's auto-merge is a QUEUE FOR CHECKS. On a repo with no PR CI there is
235	// nothing to queue behind: the mutation is rejected ("Pull request is in clean
236	// status"), and since the failure was swallowed the PR sat open forever — a repo
237	// that asked for `auto-merge` got no merge at all. Seven of twelve consumers were
238	// in exactly that shape (no `pull_request` trigger anywhere in .github/workflows).
239	//
240	// So: no CI to wait for → MERGE IT, which is what `auto-merge` meant all along.
241	//
242	// `hasPrCi` comes from ciDispatchPlan over the branch's own workflow files —
243	// `dispatch` (startable) plus `missing` (PR-triggered but not dispatchable). Both
244	// empty means no workflow anywhere runs on a pull_request, so no check will ever
245	// appear. That is a fact about the tree, not a race against checks registering.
246	//
247	// `gate` is what the BASE BRANCH requires (classifyMergeGate) — the thing
248	// GitHub's auto-merge actually queues behind. CI existing was the wrong
249	// predicate (#677): on an unprotected base the PR is mergeable the whole time
250	// its checks run, so `enablePullRequestAutoMerge` is rejected "clean status"
251	// every cycle no matter how green — arming there is doomed, and the delivery
252	// goes straight to verify-then-land instead. `unknown` arms: a gate we could
253	// not see is never merged past.
254	export function deliveryAction({ delivery, hasPrCi, gate = 'unknown' }) {
255	  if (delivery !== 'auto-merge') return 'none';
256	  if (!hasPrCi) return 'merge';
257	  return gate === 'absent' ? 'land' : 'arm';
258	}
259	
260	// What the base branch requires before a merge, from the two reads the Action's
261	// GITHUB_TOKEN can make: the branch's `protected` flag and the ruleset rules
262	// that apply to it (deliberately NOT /branches/{base}/protection, which wants
263	// admin). Rule types that queue a PR gate it; rules about pushes and deletions
264	// do not. An unreadable answer is UNKNOWN, never absent — unknown assumes a
265	// gate, so the caller arms rather than merging past a gate it cannot see.
266	const GATING_RULE_TYPES = ['pull_request', 'required_status_checks', 'merge_queue', 'required_deployments'];
267	export function classifyMergeGate({ branchStatus, branchJson, rulesStatus, rulesJson }) {
268	  if (branchStatus !== 200 || typeof branchJson?.protected !== 'boolean') return 'unknown';
269	  if (branchJson.protected) return 'present';
270	  if (rulesStatus !== 200 || !Array.isArray(rulesJson)) return 'unknown';
271	  return rulesJson.some((r) => GATING_RULE_TYPES.includes(r?.type)) ? 'present' : 'absent';
272	}
273	
274	export async function readMergeGate(token, repo, base) {
275	  const branch = await gh(token, `/repos/${repo}/branches/${encodeURIComponent(base)}`);
276	  const rules = await gh(token, `/repos/${repo}/rules/branches/${encodeURIComponent(base)}`);
277	  return classifyMergeGate({
278	    branchStatus: branch.status, branchJson: branch.json,
279	    rulesStatus: rules.status, rulesJson: rules.json,
280	  });
281	}
282	
283	// --- judging a PR by the runs on its head (#455/#205/#95) ---------------------
284	// Arming is best-effort and can fail PERMANENTLY, so "arm and move on" is not a
285	// delivery guarantee. Two shapes, both observed across the fleet, both leaving a
286	// green PR open forever:
287	//
288	//   1. GATED CI. GitHub CREATES the pull_request run for a GITHUB_TOKEN push and
289	//      parks it at conclusion `action_required`, pending a human "Approve and
290	//      run" that nobody is watching for. The run never executes, so it never
291	//      reports; `enablePullRequestAutoMerge` then refuses the PR with "in
292	//      unstable status (required checks are failing)". Meanwhile the
293	//      workflow_dispatch run started on the SAME head sha ran and passed. So CI
294	//      did pass; only the phantom gated run says otherwise.
295	//   2. AUTO-MERGE OFF. The repo never enabled Settings → General → "Allow
296	//      auto-merge", so the mutation is rejected outright no matter how green.
297	//
298	// Both are settled by the same evidence: the runs on the PR's own head sha. If
299	// CI has CONCLUDED and nothing actually failed, the content on that sha is
300	// verified and `auto-merge` means merge it. A gated `action_required` run is not
301	// a failure — it is a run that never happened.
302	//
303	// Deliberately conservative about MERGING, because that bypasses the arm:
304	//   - Anything still queued/running → `wait`. Never merge mid-flight.
305	//   - Any real failure (failure / timed_out / cancelled / startup_failure), or no
306	//     successful run to stand on → `close`: NOT a merge, and equally not a reuse.
307	//     (What `close` means is the CALLER's policy — a delivery closes and re-cuts
308	//     its per-cycle branch; a landing pass just leaves the PR standing.)
309	//
310	// A `review` member's PR is the owner's to act on, on their own clock — never
311	// merged, and never closed out from under them either.
312	export const REAL_FAILURES = ['failure', 'timed_out', 'cancelled', 'startup_failure'];
313	
314	export function pullDisposition({ delivery, runs }) {
315	  if (delivery !== 'auto-merge') return 'keep';
316	  const list = (runs ?? []).filter(Boolean);
317	  if (list.some((r) => r.status !== 'completed')) return 'wait';
318	  if (list.some((r) => REAL_FAILURES.includes(r.conclusion))) return 'close';
319	  if (!list.some((r) => r.conclusion === 'success')) return 'close';
320	  return 'merge';
321	}
322	
323	// Why the merge had to happen here rather than through the arm. The log line has
324	// to name which shape this was, or the repo misconfiguration behind it stays
325	// invisible — and it is a REPO setting, so only a human can retire it.
326	export function mergeReason(runs) {
327	  // The no-remedy shape names no setting (#677): on a base that requires
328	  // nothing, landing here IS the design, and sending an owner to fix something
329	  // already correct is worse than saying nothing.
330	  return (runs ?? []).some((r) => r?.conclusion === 'action_required')
331	    ? 'its pull_request run is parked at action_required (never ran) while the dispatched run passed'
332	    + ' — check Settings → Actions → General → workflow-approval requirements'
333	    : 'its dispatched checks concluded green and nothing on the base branch queues an auto-merge';
334	}
335	
336	// Why a PR was left (or closed) rather than merged — the same visibility
337	// argument, for the case that matters more: a member whose CI is genuinely red.
338	export function failureSummary(runs) {
339	  const failed = (runs ?? []).filter((r) => REAL_FAILURES.includes(r?.conclusion));
340	  if (failed.length) return `failing CI: ${failed.map((r) => `${r.name} ${r.conclusion}`).join(', ')}`;
341	  return 'no successful run on its head sha';
342	}
343	
344	// --- disposing of the PREVIOUS cycle's delivery (#787) ------------------------
345	// A task that delivers on a per-cycle branch must dispose of the last cycle's PR
346	// before cutting its own, or the two accumulate: the incumbent can no longer merge
347	// (its diff is landed by the newcomer) and nothing else will ever close it.
348	//
349	// Found by head-branch PREFIX, because the name carries a per-cycle date and seed —
350	// the prefix is what identifies the family. The whole PR is returned rather than its
351	// ref alone: disposal needs its number and head sha.
352	export function openDeliveredPull(pulls, prefix) {
353	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
354	}
355	
356	// The I/O half: read the runs on that PR's head, decide with the SAME predicate the
357	// landing poll uses, and either merge it (its content was verified — only the arm
358	// failed) or close it and delete its branch so this cycle re-cuts from scratch.
359	//
360	// Returns which disposal happened, because the three outcomes leave the caller in
361	// three different places and a bare null conflates two of them:
362	//
363	//   'kept'   — it still stands (a `wait`, a `review` member, or a failed attempt).
364	//              Do not deliver on top of it; leaving ONE PR alive is the whole point.
365	//   'closed' — the way is clear and main is unchanged, so this cycle re-cuts.
366	//   'merged' — the way is clear but MAIN JUST MOVED, and this job's checkout predates
367	//              it. Converging on that stale tree would re-deliver a diff already on
368	//              main, which GitHub refuses ("No commits between…") and which would in
369	//              any case be the duplicate this whole helper exists to prevent. The
370	//              caller ends its cycle instead; the next one starts from fresh main.
371	//
372	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it was
373	// found, because a cycle that cannot dispose of the incumbent must skip rather than
374	// pile a second PR on top of it.
375	export async function disposeOpenPull({ token, repo, pr, delivery, log = console.log }) {
376	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
377	  if (status !== 200) {
378	    log(`could not read the runs for PR #${pr.number}'s head (HTTP ${status}) — leaving it`);
379	    return 'kept';
380	  }
381	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
382	  const disposition = pullDisposition({ delivery, runs });
383	
384	  if (disposition === 'keep' || disposition === 'wait') {
385	    log(`keeping PR #${pr.number} (${disposition})`);
386	    return 'kept';
387	  }
388	
389	  if (disposition === 'merge') {
390	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
391	      method: 'PUT', body: { merge_method: 'squash' },
392	    });
393	    if (res.status === 200) {
394	      log(`merged PR #${pr.number} — ${mergeReason(runs)}`);
395	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
396	      return 'merged';
397	    }
398	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
399	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
400	  }
401	
402	  // Closed, not left to rot: whatever went wrong on that head, the next converge
403	  // reproduces the same content from the same inputs. Named in the log because a
404	  // member closing its delivery every single cycle is a repo whose CI needs a human,
405	  // and the pattern has to be visible to be noticed.
406	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
407	  if (closed.status !== 200) {
408	    log(`could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
409	    return 'kept';
410	  }
411	  log(`closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
412	  await deleteBranch({ token, repo, ref: pr.head?.ref, log });
413	  return 'closed';
414	}
415	
416	// --- landing THIS run's PR when the arm could not (#649) ----------------------
417	// On a member whose pull_request run is gated, EVERY arm fails; deferring to the
418	// next cycle's disposal put a standing ~24h offset between a task's output and
419	// that member's main. The evidence that settles it does not take a day to
420	// arrive: the dispatched run this delivery just started finishes in seconds. So
421	// we wait for it, once, and merge on exactly the reasoning disposal uses. Same
422	// decision, made now.
423	//
424	// Bounded and cheap because it only runs where the arm ALREADY failed (or was
425	// skipped as doomed): a healthy member arms and returns without waiting at all.
426	export const LAND_TIMEOUT_MS = 180_000;
427	export const LAND_POLL_MS = 5_000;
428	
429	// What one poll of the head sha's runs says to do: `merge`, `poll` again, or
430	// `give-up` and leave the PR standing.
431	//
432	// It NEVER closes. A cycle's disposal may close a PR because that PR is LAST
433	// cycle's and this cycle is about to re-cut it; here the PR IS this run's
434	// delivery, and closing it would throw away the work that just ran. A red member
435	// therefore leaves its PR open for the next run (or a human) to dispose of.
436	// `expected` is how many verification runs THIS delivery dispatched on the head
437	// seconds ago. Fewer visible runs than that is the API still registering them —
438	// a POLL, never a verdict. Without it, the first read 0.3s after the dispatch
439	// found an empty list and judged "nothing will ever verify this", stranding
440	// seven members' green PRs in one forced fleet pass (2026-08-07).
441	export function landAttempt({ delivery, runs, expected = 0, elapsedMs = 0, timeoutMs = LAND_TIMEOUT_MS }) {
442	  if ((runs ?? []).length < expected) return elapsedMs >= timeoutMs ? 'give-up' : 'poll';
443	  const disposition = pullDisposition({ delivery, runs });
444	  if (disposition === 'merge') return 'merge';
445	  if (disposition === 'wait') return elapsedMs >= timeoutMs ? 'give-up' : 'poll';
446	  return 'give-up';
447	}
448	
449	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
450	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
451	export async function enableAutoMerge(token, pullRequestId) {
452	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
453	  const res = await fetch(`${API}/graphql`, {
454	    method: 'POST',
455	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
456	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
457	  });
458	  const json = await res.json().catch(() => null);
459	  if (json?.errors?.length) throw new Error(json.errors[0].message);
460	}
461	
462	// Tidy the ref behind a merged (or disposed) PR — a dead branch left on the
463	// remote is litter that accumulates one per run. Never fatal: the branch is not
464	// the deliverable.
465	export async function deleteBranch({ token, repo, ref, log = console.log }) {
466	  if (!ref) return;
467	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
468	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
469	}
470	
471	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
472	
473	// The I/O half of same-run landing: poll this PR's head sha until its runs have
474	// concluded, then merge on the same evidence disposal would use a cycle later.
475	// Returns true iff it merged. Best-effort throughout — every failure path leaves
476	// the PR exactly as the arm left it, which is what the next run expects.
477	export async function landNow({ token, repo, pr, delivery, expected = 0, log = console.log }) {
478	  const started = Date.now();
479	  for (;;) {
480	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
481	    if (status !== 200) {
482	      log(`could not read this run's checks for PR #${pr.number} (HTTP ${status}) — leaving it for the next run`);
483	      return false;
484	    }
485	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
486	    const attempt = landAttempt({ delivery, runs, expected, elapsedMs: Date.now() - started });
487	
488	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
489	    if (attempt === 'give-up') {
490	      log(`PR #${pr.number} not landable this run (${failureSummary(runs)})`
491	        + ' — leaving it open for the next run to dispose of');
492	      return false;
493	    }
494	
495	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
496	      method: 'PUT', body: { merge_method: 'squash' },
497	    });
498	    if (res.status === 200) {
499	      log(`merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
500	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
501	      return true;
502	    }
503	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
504	      + ' — leaving it for the next run');
505	    return false;
506	  }
507	}
508	
509	// The whole landing, composed — what a task's delivery calls once its PR exists.
510	// Dispatch the PR's checks (they establish `hasPrCi`, the fact deliveryAction
511	// turns on), read what the base requires, then merge / land / arm per the
512	// decision — with the landing poll as fallback for a failed arm. `pr` must carry
513	// the CURRENT head ({ number, node_id, head: { ref, sha } }): after a force-push,
514	// a stale sha polls runs that will never conclude.
515	//
516	// Returns { merged, action }. `action: 'none'` is the review member — the PR
517	// stands, deliberately, and that is a delivered outcome, not a failure.
518	export async function landDelivery({ token, repo, base, pr, delivery, log = console.log }) {
519	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open emitted no
520	  // pull_request event, so without this the PR has no runs (#565). AFTER the
521	  // push, so the dispatched runs execute the branch's own head. Best-effort: a
522	  // dispatch failure must not fail the delivery that was already pushed. Run for
523	  // review members too — their owner wants green checks to review against.
524	  const ci = await dispatchCiRuns({ token, repo, branch: pr.head?.ref, log })
525	    .catch((e) => { log(`CI dispatch on ${pr.head?.ref} failed: ${e.message}`); return null; });
526	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
527	  // How many verification runs this delivery ACTUALLY started on the head — what
528	  // the landing poll waits to see registered before it judges anything
529	  // (landAttempt). `started`, never the plan: a rejected dispatch POST starts
530	  // nothing, and waiting on the plan wedges the poll against a run that can
531	  // never come.
532	  const expected = ci?.started?.length ?? 0;
533	
534	  const gate = await readMergeGate(token, repo, base).catch(() => 'unknown');
535	  const action = deliveryAction({ delivery, hasPrCi, gate });
536	  let merged = false;
537	
538	  if (action === 'merge') {
539	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
540	      method: 'PUT', body: { merge_method: 'squash' },
541	    });
542	    if (res.status === 200) { merged = true; log(`merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
543	    else log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
544	  } else if (action === 'land') {
545	    // The base requires nothing, so auto-merge has no queue to wait behind and
546	    // the arm mutation would be rejected "clean status" — every run, no setting
547	    // to fix (#677). Skip the doomed arm; wait for this run's own dispatched
548	    // evidence and land on it. Delivery must land every cycle, not heal next cycle.
549	    log(`${base} requires nothing to merge — skipping the doomed auto-merge arm;`
550	      + ` waiting for this run's ${expected} dispatched run(s) and landing PR #${pr.number} here`);
551	    merged = await landNow({ token, repo, pr, delivery, expected, log });
552	  } else if (action === 'arm' && pr.node_id) {
553	    // Surfaced, not swallowed: a failed arm is why a delivered PR sits open
554	    // forever, and the two usual causes are both fixable repo settings.
555	    const armed = await enableAutoMerge(token, pr.node_id).then(() => true)
556	      .catch((e) => {
557	        log(`could not arm auto-merge on PR #${pr.number}: ${e.message}`
558	          + ' — check Settings → General → "Allow auto-merge", and Settings → Actions → General for a'
559	          + ' workflow-approval requirement parking this PR\'s pull_request run at action_required.'
560	          + ' Waiting for this run\'s dispatched checks and landing it here.');
561	        return false;
562	      });
563	    // Only where the arm failed. A member that armed is GitHub's to land, and
564	    // waiting on it here would add a poll to every healthy repo for nothing.
565	    if (!armed) merged = await landNow({ token, repo, pr, delivery, expected, log });
566	  }
567	  return { merged, action };
568	}
569

